'use strict';

// MODULES //

var iterationOrder = require( '@stdlib/ndarray/base/iteration-order' );
var minmaxViewBufferIndex = require( '@stdlib/ndarray/base/minmax-view-buffer-index' ).assign;
var ndarraylike2descriptor = require( '@stdlib/ndarray/base/ndarraylike2descriptor' );
var isRowMajorString = require( '@stdlib/ndarray/base/assert/is-row-major-string' );
var strides2order = require( '@stdlib/ndarray/base/strides2order' );
var assign = require( '@stdlib/ndarray/base/assign' );
var descriptor = require( '@stdlib/ndarray/base/descriptor' );
var empty = require( '@stdlib/ndarray/base/empty' );


// FUNCTIONS //

/**
* Returns an input ndarray.
*
* @private
* @param {Object} x - input ndarray descriptor
* @returns {Object} input ndarray descriptor
*/
function identity( x ) {
	return x;
}

/**
* Broadcasts an ndarray containing a single element to a two-dimensional ndarray view containing a single element.
*
* @private
* @param {Object} x - input ndarray descriptor
* @returns {Object} broadcasted ndarray view descriptor
*/
function broadcast( x ) {
	return descriptor( x.dtype, x.data, [ 1, 1 ], [ 0, 0 ], x.offset, x.order );
}

/**
* Returns a function which returns a two-dimensional ndarray view of an input ndarray having only one non-singleton dimension.
*
* ## Notes
*
* -   The returned view is a row vector (i.e., a singleton dimension is prepended to the non-singleton dimension).
*
* @private
* @param {Object} arr - original ndarray descriptor
* @param {integer} index - index of the non-singleton dimension
* @returns {Function} function for returning a two-dimensional ndarray view
*/
function vector( arr, index ) {
	var sh = [ 1, arr.shape[ index ] ];
	var sx = [ arr.strides[ index ], arr.strides[ index ] ];
	return reshape;

	/**
	* Returns a two-dimensional ndarray view of an input ndarray having only one non-singleton dimension.
	*
	* @private
	* @param {Object} x - input ndarray descriptor
	* @returns {Object} a two-dimensional ndarray view descriptor
	*/
	function reshape( x ) {
		return descriptor( x.dtype, x.data, sh, sx, x.offset, x.order );
	}
}

/**
* Returns a function which returns an ndarray view in which the singleton dimensions are removed from an input ndarray having exactly two non-singleton dimensions.
*
* @private
* @param {Object} arr - original ndarray descriptor
* @param {Array<integer>} indices - indices of the non-singleton dimensions
* @returns {Function} function for returning an ndarray view
*/
function squeeze( arr, indices ) {
	var sh = [ arr.shape[ indices[0] ], arr.shape[ indices[1] ] ];
	var sx = [ arr.strides[ indices[0] ], arr.strides[ indices[1] ] ];
	return reshape;

	/**
	* Returns an ndarray view in which the singleton dimensions are removed from an input ndarray having exactly two non-singleton dimensions.
	*
	* @private
	* @param {Object} x - input ndarray descriptor
	* @returns {Object} a squeezed ndarray view descriptor
	*/
	function reshape( x ) {
		return descriptor( x.dtype, x.data, sh, sx, x.offset, x.order );
	}
}

/**
* Returns a function which returns a two-dimensional ndarray view of a contiguous input ndarray having more than two dimensions.
*
* ## Notes
*
* -   For row-major ndarrays, all but the last non-singleton dimension are collapsed into the "row" dimension. For column-major ndarrays, all but the first non-singleton dimension are collapsed into the "column" dimension.
*
* @private
* @param {Object} arr - original ndarray descriptor
* @param {Array<integer>} indices - indices of the non-singleton dimensions
* @param {integer} len - number of elements in an ndarray
* @param {integer} iox - iteration order
* @param {boolean} rowMajor - boolean indicating whether an ndarray is stored in row-major order
* @returns {Function} function for returning a two-dimensional ndarray view
*/
function contiguous( arr, indices, len, iox, rowMajor ) {
	var xmmv;
	var ind;
	var sh;
	var sx;
	var M;
	var N;

	// Resolve the index of the min/max view buffer element which is the first indexed element...
	if ( iox === 1 ) {
		ind = 0;
	} else {
		ind = 1;
	}
	// Initialize an array for storing the min/max view buffer elements:
	xmmv = [ 0, 0 ]; // [ min, max ]

	// Initialize the output two-dimensional view's shape and strides...
	if ( rowMajor ) {
		N = arr.shape[ indices[ indices.length-1 ] ];
		M = len / N;
		sx = [ iox*N, iox ];
	} else {
		M = arr.shape[ indices[ 0 ] ];
		N = len / M;
		sx = [ iox, iox*M ];
	}
	sh = [ M, N ];

	return reshape;

	/**
	* Returns a two-dimensional ndarray view of a contiguous input ndarray having more than two dimensions.
	*
	* @private
	* @param {Object} x - input ndarray descriptor
	* @returns {Object} a two-dimensional ndarray view descriptor
	*/
	function reshape( x ) {
		// Resolve the minimum and maximum linear indices in the underlying data buffer which are accessible to the input ndarray view:
		minmaxViewBufferIndex( x.shape, x.strides, x.offset, xmmv );

		// Note: `xmmv[ ind ]` corresponds to the index of the first indexed element
		return descriptor( x.dtype, x.data, sh, sx, xmmv[ ind ], x.order );
	}
}

/**
* Returns a function which copies an input ndarray to a contiguous ndarray workspace.
*
* @private
* @param {Object} arr - original ndarray descriptor
* @param {Array<integer>} indices - indices of the non-singleton dimensions
* @param {integer} len - number of elements in an ndarray
* @param {Object} workspace - ndarray workspace descriptor
* @param {boolean} rowMajor - boolean indicating whether an ndarray is stored in row-major order
* @returns {Function} function which copies an input ndarray to a contiguous ndarray workspace
*/
function copyToWorkspace( arr, indices, len, workspace, rowMajor ) {
	var view;
	var sh;
	var sx;
	var M;
	var N;

	// Initialize the workspace's two-dimensional view's shape and strides...
	if ( rowMajor ) {
		N = arr.shape[ indices[ indices.length-1 ] ];
		M = len / N;
		sx = [ N, 1 ];
	} else {
		M = arr.shape[ indices[ 0 ] ];
		N = len / M;
		sx = [ 1, M ];
	}
	sh = [ M, N ];

	view = descriptor( workspace.dtype, workspace.data, sh, sx, workspace.offset, workspace.order ); // eslint-disable-line max-len
	return reshape;

	/**
	* Copies an input ndarray to a contiguous ndarray workspace and returns a two-dimensional workspace view.
	*
	* @private
	* @param {Object} x - input ndarray descriptor
	* @returns {Object} two-dimensional workspace view descriptor
	*/
	function reshape( x ) {
		assign( [ x, workspace ] );
		return view;
	}
}

/**
* Returns a function which copies from a contiguous ndarray workspace to an input ndarray.
*
* @private
* @param {Object} workspace - ndarray workspace descriptor
* @returns {Function} function which copies from a contiguous ndarray workspace to an input ndarray
*/
function copyFromWorkspace( workspace ) {
	return copy;

	/**
	* Copies from a contiguous ndarray workspace to an input ndarray.
	*
	* @private
	* @param {Object} x - input ndarray descriptor
	* @returns {Object} input ndarray descriptor
	*/
	function copy( x ) {
		assign( [ workspace, x ] );
		return x;
	}
}


// MAIN //

/**
* Returns an object containing methods for reshaping an ndarray as a two-dimensional strided array view.
*
* @param {Object} x - ndarray descriptor
* @param {*} x.dtype - ndarray data type
* @param {Collection} x.data - ndarray data buffer
* @param {Array<integer>} x.shape - ndarray shape
* @param {Array<integer>} x.strides - ndarray strides
* @param {integer} x.offset - ndarray index offset
* @param {string} x.order - ndarray memory layout
* @returns {Object} object containing methods implementing a reshape strategy
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
*
* var x = {
*     'dtype': 'float64',
*     'data': new Float64Array( [ 1.0, 2.0, 3.0, 4.0 ] ),
*     'shape': [ 2, 2 ],
*     'strides': [ 2, 1 ],
*     'offset': 0,
*     'order': 'row-major'
* };
*
* var out = strategy( x );
* // returns {...}
*/
function strategy( x ) {
	var workspace;
	var rowMajor;
	var indices;
	var ndims;
	var xmmv;
	var len;
	var iox;
	var ord;
	var sh;
	var i;

	// Resolve the number of array dimensions:
	sh = x.shape;
	ndims = sh.length;

	// Check whether the ndarray is already two-dimensional...
	if ( ndims === 2 ) {
		return {
			'input': identity,
			'output': identity
		};
	}
	// Resolve the indices of the non-singleton dimensions...
	len = 1;      // number of elements
	indices = []; // indices of non-singleton dimensions
	for ( i = 0; i < ndims; i++ ) {
		// Check whether the current dimension is a non-singleton dimension...
		if ( sh[ i ] !== 1 ) {
			indices.push( i );
		}
		len *= sh[ i ];
	}
	// Determine whether the ndarray only contains a single element (e.g., ndims=0 or ndims=3, shape=[1,1,1]) so that we can simply broadcast to a two-dimensional ndarray view...
	if ( indices.length === 0 ) {
		return {
			'input': broadcast,
			'output': identity
		};
	}
	// Determine whether the ndarray has only **one** non-singleton dimension (e.g., ndims=1 or ndims=4, shape=[1,1,5,1]) so that we can simply create a row vector view...
	if ( indices.length === 1 ) {
		return {
			'input': vector( x, indices[ 0 ] ),
			'output': identity
		};
	}
	// Determine whether the ndarray has exactly **two** non-singleton dimensions (e.g., ndims=4, shape=[10,1,5,1]) so that we can simply create an ndarray view without the singleton dimensions...
	if ( indices.length === 2 ) {
		return {
			'input': squeeze( x, indices ),
			'output': identity
		};
	}
	// Resolve the memory layout which determines which dimensions are collapsed:
	rowMajor = isRowMajorString( x.order );

	iox = iterationOrder( x.strides ); // +/-1

	// Determine whether we can avoid copying data...
	if ( iox !== 0 ) {
		// Determine the minimum and maximum linear indices which are accessible by the ndarray view:
		xmmv = minmaxViewBufferIndex( sh, x.strides, x.offset, [ 0, 0 ] );

		// Determine whether the ndarray is contiguous...
		if ( len === ( xmmv[1]-xmmv[0]+1 ) ) {
			// In order to collapse dimensions, the ndarray elements must be arranged in memory according to the ndarray's memory layout; otherwise, the collapsed dimensions would fail to have uniform strides...
			ord = strides2order( x.strides ); // 0=none, 1=row-major, 2=column-major, 3=both

			// Determine whether we can ignore shape (and strides) and create a new two-dimensional ndarray view...
			if ( ord === 3 || ( rowMajor && ord === 1 ) || ( !rowMajor && ord === 2 ) ) { // eslint-disable-line max-len
				return {
					'input': contiguous( x, indices, len, iox, rowMajor ),
					'output': identity
				};
			}
			// The ndarray elements are not arranged in memory according to the ndarray's memory layout, so we cannot directly interpret as a two-dimensional ndarray...

			// Fall-through to copying to a workspace ndarray...
		}
		// The ndarray is non-contiguous, so we cannot directly interpret as a two-dimensional ndarray...

		// Fall-through to copying to a workspace ndarray...
	}
	// At this point, we're dealing with an ndarray which cannot be interpreted as a two-dimensional ndarray view, so we need to copy to a contiguous workspace:
	workspace = ndarraylike2descriptor( empty( x.dtype, x.shape, x.order ) );
	return {
		'input': copyToWorkspace( x, indices, len, workspace, rowMajor ),
		'output': copyFromWorkspace( workspace )
	};
}


// EXPORTS //

module.exports = strategy;
